{"command": "cat > /tmp/mcp_client.py <<'PYEOF'
#!/usr/bin/env python3
"""Minimal stdio MCP client for `arch-ml mcp serve` (NDJSON JSON-RPC).

Usage: python3 mcp_client.py <journal-path> <repo> [tool ...]
"""
import json
import select
import subprocess
import sys


def main() -> int:
    journal, repo = sys.argv[1], sys.argv[2]
    tools = sys.argv[3:]
    run_id = "theseus-mosaic-kda-20261010101546-selfcheck"
    proc = subprocess.Popen(
        ["arch-ml", "mcp", "serve", "--run-id", run_id, "--journal", journal],
        stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
        text=True, bufsize=1,
    )

    def send(msg):
        proc.stdin.write(json.dumps(msg, ensure_ascii=False) + "\n")
        proc.stdin.flush()

    def recv(timeout=180):
        r, _, _ = select.select([proc.stdout], [], [], timeout)
        if not r:
            raise TimeoutError("no response from MCP server")
        line = proc.stdout.readline()
        if not line:
            raise RuntimeError("MCP server closed stdout: " + proc.stderr.read()[:2000])
        return json.loads(line)

    send({"jsonrpc": "2.0", "id": 1, "method": "initialize",
          "params": {"protocolVersion": "2024-11-05", "capabilities": {},
                     "clientInfo": {"name": "theseus", "version": "0.1"}}})
    print("initialize:", json.dumps(recv(), ensure_ascii=False)[:300])
    send({"jsonrpc": "2.0", "method": "notifications/initialized", "params": {}})

    next_id = 2
    rc = 0
    if not tools:
        send({"jsonrpc": "2.0", "id": next_id, "method": "tools/list"})
        resp = recv()
        for t in resp.get("result", {}).get("tools", []):
            print(f"- {t['name']}: {t.get('description', '')[:150]}")
            print(f"    schema: {json.dumps(t.get('inputSchema', {}), ensure_ascii=False)[:260]}")
    else:
        for tool in tools:
            next_id += 1
            send({"jsonrpc": "2.0", "id": next_id, "method": "tools/call",
                  "params": {"name": tool, "arguments": {"repo": repo}}})
            resp = recv()
            print(f"=== {tool} ===")
            print(json.dumps(resp, ensure_ascii=False)[:4000])
            result = resp.get("result", {})
            structured = result.get("structuredContent")
            passed = None
            if isinstance(structured, dict):
                passed = structured.get("passed")
            else:
                for block in result.get("content", []):
                    if block.get("type") == "text":
                        try:
                            passed = json.loads(block["text"]).get("passed")
                        except Exception:
                            pass
            if passed is not True:
                rc = 1
    proc.stdin.close()
    proc.terminate()
    try:
        proc.wait(timeout=10)
    except subprocess.TimeoutExpired:
        proc.kill()
    return rc


if __name__ == "__main__":
    raise SystemExit(main())
